#!/bin/sh
if test "$#" -eq 1; then eval "set -- $1"; fi
livespec_record_file() { record_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-record-file-resolution.py"; if test ! -f "$record_program"; then echo "LIVESPEC_RECORD_FILE_PROGRAM_ABSENT: the Dispatcher-materialized generated-record-file resolution is not at $record_program, so whether a conflicted or committed generated record file matches its generator cannot be established" >&2; return 1; fi; python3 "$record_program" --state-dir "$state" "$@"; }; livespec_record_file_brief() { regen_brief=; if livespec_record_file --brief "$@"; then regen_brief=$(cat "$state/livespec-record-file-regenerate" 2>/dev/null || true); fi; }; livespec_record_file_merge() { merge_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-record-file-merge.py"; if test ! -f "$merge_program"; then echo "LIVESPEC_RECORD_FILE_MERGE_PROGRAM_ABSENT: the Dispatcher-materialized record-file merger is unavailable, so this conflict takes refresh repair" >&2; return 1; fi; merge_mode=$1; shift; python3 "$merge_program" --mode "$merge_mode" "$@"; }; livespec_rebase_active() { test -d "$(git rev-parse --git-path rebase-merge)" || test -d "$(git rev-parse --git-path rebase-apply)"; }; livespec_regenerating_rebase() { if git rebase $rebase_flags "$1"; then return 0; fi; regen_rounds=0; while test "$regen_rounds" -lt 16; do regen_rounds=$((regen_rounds + 1)); if ! livespec_rebase_active; then git merge-base --is-ancestor "$1" HEAD; return $?; fi; regen_conflicted=$(git diff --name-only --diff-filter=U); if test -z "$regen_conflicted"; then return 1; fi; if livespec_record_file --resolve $regen_conflicted; then :; elif livespec_record_file_merge rebase $regen_conflicted; then :; else return 1; fi; GIT_EDITOR=true git rebase --continue || true; done; return 1; }; livespec_push() {
  helper=$(printenv LIVESPEC_SANDBOX_GH_REFRESH_ROOT || true)
  if test -z "$helper"; then helper=/workspace/.livespec-gh-refresh; fi
  helper="$helper/bin/push_origin"
  if test -x "$helper"; then
    "$helper" "$@"
  else
    if test -n "$(printenv GITHUB_APP_ID)"; then
      case "$(git remote get-url --push origin)" in
        http://*|https://*)
          echo "LIVESPEC_PUSH_AUTH_ABSENT: push-time credential helper is missing" >&2
          return 1
          ;;
      esac
    fi
    "$@"
  fi
}
livespec_restore() { restore_head="$1"; if test -d "$(git rev-parse --git-path rebase-merge)" || test -d "$(git rev-parse --git-path rebase-apply)"; then git rebase --abort >/dev/null 2>&1 || true; fi; if test -f "$(git rev-parse --git-path MERGE_HEAD)"; then git merge --abort >/dev/null 2>&1 || true; fi; git reset --keep "$restore_head" >/dev/null 2>&1; }; livespec_refresh_repair() { repair_stage="$1"; repair_target="$2"; repair_label="$3"; repair_detail="$4"; repair_commit="$5"; repair_extra="${6:-}"; if test "$repair_count" -ge 2; then printf '%s\n' "refresh-repair-exhausted: $repair_stage would need a third refresh repair after $repair_count rounds, so this run is not converging on the moved default branch; recovery artifact pointer: this stage pre-refresh head is $pre_refresh" > "$reason_path"; echo "LIVESPEC_REFRESH_REPAIR_EXHAUSTED: refresh-repair-exhausted after $repair_count rounds; $repair_stage restored $pre_refresh and is failing closed to needs_human with that head as the recovery artifact pointer" >&2; return 0; fi; { printf 'LIVESPEC_REFRESH_REPAIR_BRIEF\n'; printf 'stage: %s\n' "$repair_stage"; printf 'pre-refresh-head: %s\n' "$pre_refresh"; printf 'refresh-target: %s\n' "$repair_target"; printf 'run-commit: %s\n' "$repair_commit"; printf '%s: %s\n' "$repair_label" "$repair_detail"; if test -n "$repair_extra"; then printf '%s\n' "$repair_extra"; fi; } > "$state/livespec-refresh-repair-brief"; printf '%s\n' "$((repair_count + 1))" > "$state/livespec-refresh-repair-count"; echo "LIVESPEC_REFRESH_REPAIR: $repair_stage restored $pre_refresh and recorded a refresh-repair brief, so this failure enters the fix node rather than needs_human" >&2; cat "$state/livespec-refresh-repair-brief" >&2; return 0; }; livespec_started_empty() { for started_empty in $(git rev-list --no-merges "$1..$2"); do if test -z "$(git diff-tree --no-commit-id --name-only -r "$started_empty")"; then printf '%s ' "$started_empty"; fi; done; }; livespec_own_empty_checkpoint_range() { checkpoint_run=$(git config --local --get livespec.factoryRunId 2>/dev/null || true); if test -z "$checkpoint_run" || ! git merge-base --is-ancestor "$1" "$2"; then return 1; fi; for checkpoint in $(git rev-list --reverse "$1..$2"); do checkpoint_parent=$(git show -s --format=%P "$checkpoint"); case "$checkpoint_parent" in ''|*' '*) return 1 ;; esac; if test "$(git rev-parse "$checkpoint^{tree}")" != "$(git rev-parse "$checkpoint_parent^{tree}")"; then return 1; fi; case "$(git show -s --format=%s "$checkpoint")" in "fabro($checkpoint_run): "*) ;; *) return 1 ;; esac; done; return 0; }; livespec_declared_gate() { livespec_suite_words=''
for livespec_suite_word in "$@"; do
  livespec_suite_quoted=$(printf '%s' "$livespec_suite_word" | sed "s/'/'\\''/g")
  livespec_suite_words="$livespec_suite_words '$livespec_suite_quoted'"
done
set --
eval "set -- $livespec_suite_words"; if test "$#" -eq 1; then eval "set -- $1"; fi; "$@"; }; livespec_stage_cause() { cause_path=$(git rev-parse --git-path livespec-stage-cause); printf 'stage: %s\ncause: %s\n' pr_refresh "$1" > "$cause_path"; printf '%s\n' "$1" >&2; }; set -u; rm -f "$(git rev-parse --git-path livespec-stage-cause)"; branch="${LIVESPEC_PUBLISH_BRANCH:-}"; if test -z "$branch"; then livespec_stage_cause 'LIVESPEC_PR_REFRESH_NO_BRANCH: no LIVESPEC_PUBLISH_BRANCH in this script environment, so the publish branch cannot be named; failing closed before touching any ref'; exit 1; fi; state=$(git rev-parse --git-path livespec-publication); if test -z "$state"; then livespec_stage_cause 'LIVESPEC_PR_REFRESH_NO_STATE_DIR: this run publication state directory could not be resolved inside the clone, so the head this run published cannot be read; failing closed before touching any ref'; exit 1; fi; mkdir -p "$state"; rm -f "$state/livespec-pr-refresh-changed"; rm -f "$state/livespec-merged-reconcile"; rm -f "$state/livespec-refresh-repair-brief"; conflict_entry=false; if test -f "$state/livespec-pr-refresh-conflict-entry"; then conflict_entry=true; fi; rm -f "$state/livespec-pr-refresh-conflict-entry"; clean_done=false; if test -f "$state/livespec-pr-refresh-clean"; then clean_done=true; fi; reason_path=$(git rev-parse --git-path livespec-needs-human-reason); repair_count=$(cat "$state/livespec-refresh-repair-count" 2>/dev/null || echo 0); if ! test "$repair_count" -ge 0 2>/dev/null; then livespec_stage_cause "LIVESPEC_REFRESH_REPAIR_COUNT_UNREADABLE: the recorded refresh-repair count $repair_count is not a number, so the two-round repair budget cannot be enforced; failing closed rather than repairing against a counter nothing can compare"; exit 1; fi; recorded=$(cat "$state/livespec-publish-head" 2>/dev/null || true); if test -z "$recorded"; then recorded="${LIVESPEC_RESUME_PUBLISHED_HEAD:-}"; fi; if test -z "$recorded"; then livespec_stage_cause 'LIVESPEC_PR_REFRESH_NO_PROVENANCE: neither this run publication record nor a validated resume provenance names a published head, so the head this run owns cannot be established; a local tracking ref is NOT a substitute. Failing closed rather than leasing over a head nobody proved'; exit 1; fi; pre_refresh="$recorded"; remote=$(git ls-remote --heads origin "refs/heads/$branch"); remote_status=$?; if test "$remote_status" -ne 0; then livespec_stage_cause 'LIVESPEC_PR_REFRESH_ORIGIN_UNOBSERVABLE: origin could not be queried for the run publish branch; holding rather than proceeding blinded'; exit 1; fi; remote=$(printf '%s' "$remote" | cut -f 1); if test -z "$remote"; then merged=$(gh pr view "$branch" --json number,state,mergeCommit,headRefOid --jq '(.number|tostring)+"\t"+(.state|tostring)+"\t"+(.mergeCommit.oid|tostring)+"\t"+(.headRefOid|tostring)'); merged_status=$?; IFS=$(printf '\t'); set -- $merged; unset IFS; merged_number=${1:-}; merged_state=${2:-}; merged_commit=${3:-}; merged_head=${4:-}; if test "$merged_status" -eq 0 && test "$merged_state" = MERGED && test -n "$merged_number" && test "$(printf '%s' "$merged_commit" | tr -d 0123456789abcdef)" = "" && test "$(printf '%s' "$merged_commit" | wc -c)" -eq 40 && test -n "$merged_head"; then proof_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-publication-head.py"; if ! test -f "$proof_program"; then livespec_stage_cause "LIVESPEC_PR_REFRESH_ORIGIN_UNOBSERVABLE: the merged pull request proof records could not be read because the publication-head reader is absent"; exit 1; fi; proof_head=$(python3 "$proof_program" --pull-request "$merged_number" --latest-anchor-or-none); if test $? -ne 0; then livespec_stage_cause "LIVESPEC_PR_REFRESH_ORIGIN_UNOBSERVABLE: the merged pull request proof records could not be read, so its latest verified or carried_forward head cannot be established"; exit 1; fi; heads_equal=false; if test "$proof_head" = "$merged_head"; then heads_equal=true; fi; { printf 'pull_request=%s\n' "$merged_number"; printf 'merge_commit=%s\n' "$merged_commit"; printf 'merged_head=%s\n' "$merged_head"; printf 'proof_head=%s\n' "$proof_head"; printf 'heads_equal=%s\n' "$heads_equal"; } > "$state/livespec-merged-reconcile"; echo "LIVESPEC_MERGED_RECONCILE: pull_request=$merged_number merge_commit=$merged_commit merged_head=$merged_head proof_head=$proof_head heads_equal=$heads_equal" >&2; exit 0; fi; livespec_stage_cause "LIVESPEC_PR_REFRESH_ORIGIN_UNOBSERVABLE: origin carries no $branch and the pull request could not be established as MERGED with a merge commit, so the published origin cannot be observed; failing closed rather than recreating a ref whose history nobody can account for"; exit 1; fi; if ! git fetch --no-tags origin "refs/heads/$branch" "refs/heads/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}"; then livespec_stage_cause 'LIVESPEC_PR_REFRESH_ORIGIN_UNOBSERVABLE: the authoritative default branch could not be fetched after the publish branch was observed; holding rather than proceeding blinded'; exit 1; fi; remote_checkpoint_head=false; if test "$remote" != "$recorded"; then if livespec_own_empty_checkpoint_range "$recorded" "$remote"; then remote_checkpoint_head=true; else livespec_stage_cause "LIVESPEC_PR_REFRESH_FOREIGN_HEAD: origin $branch is at $remote while this run published $recorded, so the remote head is not this run own; failing closed rather than leasing over a foreign change"; exit 1; fi; fi; base=$(git rev-parse "refs/remotes/origin/${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}"); prev_base=$(git merge-base "$recorded" "$base"); if test "$clean_done" = true && test "$conflict_entry" != true && ! git merge-base --is-ancestor "$base" HEAD; then echo "LIVESPEC_PR_REFRESH_CLEAN_ONCE: the default branch advanced to $base after this run refreshed cleanly onto its predecessor $prev_base, so no further refresh onto it is owed; later default-branch movement is left to the merge path and publication proceeds with the run published head $recorded" >&2; base="$prev_base"; fi; if git merge-base --is-ancestor "$base" HEAD && test "$remote_checkpoint_head" != true; then echo "LIVESPEC_PR_REFRESH_UNCHANGED: the publish head $recorded already contains the authoritative default $base, so no rebase is owed and the verified proof still names the head that will be published" >&2; exit 0; fi; count=$(cat "$state/livespec-pr-refresh-count" 2>/dev/null || echo 0); if ! test "$count" -ge 0 2>/dev/null; then livespec_stage_cause "LIVESPEC_PR_REFRESH_COUNT_UNREADABLE: the recorded refresh count $count is not a number, so the three-refresh bound cannot be enforced; failing closed rather than refreshing against a counter nothing can compare"; exit 1; fi; if test "$count" -ge 3 && ! git merge-base --is-ancestor "$base" HEAD; then printf '%s\n' "pr-refresh-non-converged: the default branch advanced again after $count completed refreshes of this run, so publication is not converging and no further refresh is owed; the work is preserved by reference at the publish head $recorded" > "$reason_path"; livespec_stage_cause "LIVESPEC_PR_REFRESH_NON_CONVERGED: the default branch has advanced again after $count completed refreshes of this run, so publication is not converging; terminating with the work preserved rather than refreshing a fourth time"; exit 1; fi; advanced=false; if ! git merge-base --is-ancestor "$base" HEAD; then advanced=true; fi; arming=$(gh pr view "$branch" --json autoMergeRequest --jq '.autoMergeRequest|tojson') || arming=""; if test -z "$arming"; then livespec_stage_cause "LIVESPEC_PR_REFRESH_ARMING_UNREADABLE: the forge could not be asked whether the pull request for $branch carries an auto-merge request, so a rebase here could rewrite the head of a pull request the forge is holding armed for merge; failing closed before any rebase or push"; exit 1; fi; if test "$arming" != "null"; then if ! gh pr merge "$branch" --disable-auto; then livespec_stage_cause "LIVESPEC_PR_REFRESH_DISARM_FAILED: the auto-merge request on the pull request for $branch could not be removed, so the forge could merge the rebased head the moment this refresh pushes it; failing closed before any rebase or push"; exit 1; fi; echo "LIVESPEC_PR_REFRESH_DISARMED: the pull request for $branch carried an auto-merge request and it was removed before this refresh rebased; within a run only pr re-arms, and only for a head the latest verified or carried_forward record names" >&2; fi; if test -n "$(livespec_started_empty "$prev_base" HEAD)"; then rebase_flags='--no-keep-empty --force-rebase'; else rebase_flags=; fi; if ! livespec_regenerating_rebase "$base"; then conflicted=$(git diff --name-only --diff-filter=U | tr '\n' ' '); applying=$(git rev-parse --verify --quiet REBASE_HEAD || printf '%s' "$recorded"); printf '%s\n' "$((count + 1))" > "$state/livespec-pr-refresh-count"; livespec_record_file_brief $conflicted; if test -n "$conflicted" && livespec_restore "$recorded"; then livespec_refresh_repair pr_refresh "$base" conflicted-paths "$conflicted" "$applying" "$regen_brief"; exit 1; fi; git rebase --abort >/dev/null 2>&1 || true; livespec_stage_cause "LIVESPEC_PR_REFRESH_CONFLICT: rebasing $branch onto $base conflicts; the rebase was aborted and no side was chosen. The run tree is preserved by reference and the published head is untouched"; exit 1; fi; if ! python3 "${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-run-plugin-gate.py"; then livespec_stage_cause "LIVESPEC_PR_REFRESH_PLUGIN_GATE_FAILED: the sandbox plugin registry names a build this run did not resolve at start, or one whose cache this run could not repair, so the declared check suite would resolve a plugin root that does not exist and the active publication hooks cannot be trusted; failing closed before the gate and before push"; exit 1; fi; if ! livespec_record_file --check-head; then regen_targets=$(cat "$state/livespec-record-file-targets" 2>/dev/null | tr '\n' ' '); regen_brief=$(cat "$state/livespec-record-file-regenerate" 2>/dev/null || true); if test -n "$(printf '%s' "$regen_targets" | tr -d ' ')"; then printf '%s\n' "$((count + 1))" > "$state/livespec-pr-refresh-count"; if livespec_restore "$recorded"; then livespec_refresh_repair pr_refresh "$base" failed-gate-targets "$regen_targets" "$recorded" "$regen_brief"; exit 1; fi; fi; livespec_stage_cause "LIVESPEC_PR_REFRESH_GENERATED_RECORD_FILE_UNCHECKABLE: whether this head's committed generated record files are their generators' output could not be established, so the repository-declared gate would run on a head carrying a hand-merged register. Nothing was pushed"; exit 1; fi; gate_out=$(livespec_declared_gate "$@" 2>&1); gate_status=$?; printf '%s\n' "$gate_out" >&2; if test "$gate_status" -ne 0; then gate_targets=$(printf '%s\n' "$gate_out" | tail -c 2000 | tr '\n' ' '); printf '%s\n' "$((count + 1))" > "$state/livespec-pr-refresh-count"; if livespec_restore "$recorded"; then livespec_refresh_repair pr_refresh "$base" failed-gate-targets "$gate_targets" "$recorded"; exit 1; fi; livespec_stage_cause "LIVESPEC_PR_REFRESH_GATE_FAILED: the repository declared sandbox check suite failed against the rebased head, so the rebase is not publishable; nothing was pushed"; exit 1; fi; pushed=$(git rev-parse HEAD); push_program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-push-exact-head"; if test ! -x "$push_program"; then livespec_stage_cause "LIVESPEC_PR_REFRESH_PUSH_PROGRAM_ABSENT: the Dispatcher-materialized exact-head push helper is not at $push_program, so no rewrite can be proven to carry the required expected-object lease; failing closed"; exit 1; fi; if ! livespec_push "$push_program" "$branch" "$remote"; then livespec_stage_cause "LIVESPEC_PR_REFRESH_LEASE_FAILED: the leased push of $branch against the recorded remote head $remote was rejected, so the remote moved after it was observed or origin refused the write; nothing else was rewritten"; exit 1; fi; printf '%s\n' "$pushed" > "$state/livespec-publish-head"; if test "$conflict_entry" = true && test "$advanced" = true; then printf '%s\n' "$((count + 1))" > "$state/livespec-pr-refresh-count"; fi; if test "$advanced" = true; then : > "$state/livespec-pr-refresh-clean"; fi; printf '%s\n' "$recorded" > "$state/livespec-pr-refresh-previous-head"; printf '%s\n' "$prev_base" > "$state/livespec-pr-refresh-previous-base"; printf '%s\n' "$base" > "$state/livespec-pr-refresh-new-base"; printf '%s\n' "$pushed" > "$state/livespec-pr-refresh-new-head"; : > "$state/livespec-pr-refresh-changed"; if test "$remote_checkpoint_head" = true; then echo "LIVESPEC_PR_REFRESH_CHANGED: $branch leased the observed own checkpoint head $remote and republished $pushed without its empty checkpoints; the verified proof names the old head, so carry-forward must decide whether fresh proof is owed" >&2; else echo "LIVESPEC_PR_REFRESH_CHANGED: $branch was rebased onto $base, gated and republished at $pushed; the verified proof names the old head, so fresh capture, review and replay are owed before publication" >&2; fi; exit 0
